DROP FUNCTION IF EXISTS nexus.gc_quarantine_orphans_floored(int, text, text, text, text, int, int, float8, int, boolean);
CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans_floored( dim int, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit int, p_row_limit int, p_floor_fraction float8, p_floor_min_chunks int, p_force boolean, p_quarantine_expires_at text DEFAULT NULL ) RETURNS TABLE(moved bigint, sample jsonb, remaining bigint, refused boolean, reapable_count bigint, total_count bigint) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_reapable bigint; v_total bigint; v_moved bigint; v_sample jsonb; v_remaining bigint; v_repeat boolean; BEGIN IF p_row_limit IS NOT NULL AND p_row_limit <= 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: p_row_limit must be positive when given (NULL selects the unbounded sweep), got %', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
IF p_floor_fraction IS NOT NULL AND ( p_floor_fraction < 0 OR p_floor_fraction > 1 OR p_floor_min_chunks IS NULL OR p_floor_min_chunks < 0) THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: the floor must be a fraction in [0, 1] and a non-negative minimum, got % / %', p_floor_fraction, p_floor_min_chunks USING ERRCODE = 'invalid_parameter_value'; END IF;
-- The stamp is compared as text with other fixed-width stamps (reaper_expire_client_quarantine), so it must be -- that shape: any other shape could sort before now() by accident and expire a row early. IF p_quarantine_expires_at IS NOT NULL AND p_quarantine_expires_at !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: p_quarantine_expires_at must be yyyy-MM-ddTHH:mm:ssZ, got %', p_quarantine_expires_at USING ERRCODE = 'invalid_parameter_value'; END IF;
-- The judgement. Only when a floor was given and the caller did not override it. IF p_floor_fraction IS NOT NULL AND NOT COALESCE(p_force, false) THEN PERFORM set_config('lock_timeout', '2000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer is holding it; retry', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- Counted UNDER the gate, on the whole collection: the reapable set is the numerator, every -- stored chunk the denominator (the reaper's reading, vectors-024-1). SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL))) INTO v_total, v_reapable FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection;
IF v_reapable >= p_floor_min_chunks AND v_total > 0 AND v_reapable::float8 / v_total::float8 > p_floor_fraction THEN -- One row per STATE, not per call: skip the INSERT when the newest refusal row of this -- (tenant, collection) carries identical counts and floor values and is under an hour old. -- Every `nx index repo` walk repeats the same refusal for a collection that stays over the -- floor, and gc_audit has no retention. The refusal is still returned either way. SELECT EXISTS ( SELECT 1 FROM ( SELECT a.details, a.created_at FROM nexus.gc_audit a WHERE a.tenant_id = p_tenant_id AND a.collection = p_collection AND a.operation = 'gc_quarantine_orphans_refused' ORDER BY a.id DESC LIMIT 1) last WHERE last.created_at > now() - interval '1 hour' AND (last.details->>'reapable_count')::bigint = v_reapable AND (last.details->>'total_count')::bigint = v_total AND (last.details->>'floor_fraction')::float8 = p_floor_fraction AND (last.details->>'floor_min_chunks')::int = p_floor_min_chunks) INTO v_repeat; IF NOT v_repeat THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_quarantine_orphans_refused', p_collection, 'engine', false, 0, '[]'::jsonb, jsonb_build_object( 'reason', 'FLOOR', 'form', CASE WHEN p_row_limit IS NULL THEN 'unbounded' ELSE 'bounded' END, 'quarantine_collection', p_quarantine_collection, 'reapable_count', v_reapable, 'total_count', v_total, 'floor_fraction', p_floor_fraction, 'floor_min_chunks', p_floor_min_chunks)); END IF; RETURN QUERY SELECT 0::bigint, NULL::jsonb, v_reapable, true, v_reapable, v_total; RETURN; END IF; END IF;
-- The move. The existing functions take the same gate (already ours on the judged path), choose their -- victim set once, and write their own audit row. IF p_row_limit IS NULL THEN SELECT g.moved, g.sample INTO v_moved, v_sample FROM nexus.gc_quarantine_orphans( dim, p_tenant_id, p_collection, p_quarantine_collection, p_quarantined_at, p_sample_limit) g; v_remaining := NULL; ELSE SELECT g.moved, g.sample, g.remaining INTO v_moved, v_sample, v_remaining FROM nexus.gc_quarantine_orphans_bounded( dim, p_tenant_id, p_collection, p_quarantine_collection, p_quarantined_at, p_sample_limit, p_row_limit) g; END IF;
-- nexus-alsq3: the client's retention, written on the rows THIS call moved. The base functions are not -- touched, but each leaves the victim set it chose in a temp table that lives to the end of the transaction -- (_wbfpw16_victim in the unbounded form, _a6mon_victim in the bounded one; both ON COMMIT DROP, both refilled -- by every call, so what the wrapper reads is this call's set). The UPDATE joins those chashes, so it is a -- primary-key probe per moved row and never a scan of the quarantine sibling by metadata: a drain of N batches -- over a sibling of M rows costs N x batch, not N x M. A re-moved chash was rewritten by the base function's -- ON CONFLICT DO UPDATE, which carries no stamp, so a stale one cannot survive; a row already in the sibling -- from another call or another batch is not in this call's set and is not touched. Same transaction as the -- move, under the same sweep gate. A victim whose DELETE lost the last-write recheck stays live but its copy is -- already in the sibling carrying this call's quarantined_at, so it is stamped like the rest. IF p_quarantine_expires_at IS NOT NULL AND COALESCE(v_moved, 0) > 0 THEN IF p_row_limit IS NULL THEN UPDATE nexus.chunks c SET metadata = COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantine_expires_at', p_quarantine_expires_at) FROM _wbfpw16_victim v WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = v.chash; ELSE UPDATE nexus.chunks c SET metadata = COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantine_expires_at', p_quarantine_expires_at) FROM _a6mon_victim v WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = v.chash; END IF; END IF;
RETURN QUERY SELECT v_moved, v_sample, v_remaining, false, v_reapable, v_total; END; $$;
GRANT EXECUTE ON FUNCTION nexus.gc_quarantine_orphans_floored(int, text, text, text, text, int, int, float8, int, boolean, text) TO nexus_svc;

