CREATE OR REPLACE FUNCTION nexus.reaper_expire_client_quarantine( p_tenant_id text, p_quarantine_collection text, p_origin_collection text, p_cutoff text, p_row_limit int ) RETURNS TABLE(expired bigint, protected_count bigint) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_chashes bytea[]; v_protected bigint; v_deleted bytea[]; v_expired bigint; v_now text; BEGIN IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'reaper_expire_client_quarantine: p_row_limit must be positive, got %', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
-- The cutoff is compared with the rows' text stamps, so it must be the same fixed-width UTC shape: any other -- shape could sort before a stamp by accident (an offset, fractional seconds), and the caller's own bug must -- not become a mass delete. IF p_cutoff IS NULL OR p_cutoff !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' THEN RAISE EXCEPTION 'reaper_expire_client_quarantine: p_cutoff must be yyyy-MM-ddTHH:mm:ssZ, got %', p_cutoff USING ERRCODE = 'invalid_parameter_value'; END IF;
-- nexus-alsq3: the client's own retention, stamped on the row at move time as an absolute instant -- (quarantine_expires_at, the same fixed-width UTC shape). A row expires at the LATER of the engine's -- retention (the cutoff above) and the stamp: both must have passed. A row with no stamp (moved before the -- stamp existed, or by a client that does not send one) keeps the engine's retention alone. A stamp that is -- present but not that shape is no stamp: the row is judged by the engine's retention alone, so a hand-written -- bad value can never hold a row past the engine's default (quarantine-* collections are bypass collections, a -- client can write any metadata there). It cannot expire a row earlier than p_cutoff either. 'Now' is the database's transaction time, so the stamp and the clock that -- judges it are one clock. v_now := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
-- The scope, here and not only in the Java caller, every part a registry row of this tenant: the sibling is a -- registered quarantine knowledge collection, the origin a registered live knowledge collection (restore, -- vectors-025, requires a live origin too). Code, docs and rdr quarantine belongs to the client's own sweep and -- its NX_GC_QUARANTINE_DAYS. IF NOT COALESCE( starts_with(p_quarantine_collection, 'quarantine-') AND EXISTS (SELECT 1 FROM nexus.catalog_collections q WHERE q.tenant_id = p_tenant_id AND q.name = p_quarantine_collection AND q.content_type = 'knowledge' AND q.lifecycle_state = 'quarantine') AND EXISTS (SELECT 1 FROM nexus.catalog_collections o WHERE o.tenant_id = p_tenant_id AND o.name = p_origin_collection AND o.content_type = 'knowledge' AND o.lifecycle_state = 'live'), false) THEN RETURN QUERY SELECT 0::bigint, 0::bigint; RETURN; END IF;
PERFORM set_config('lock_timeout', '2000', true);
-- Past the cutoff, client-moved rows (the reaper does not own them) of this origin that a manifest row of the -- origin still names: never deleted, counted so the caller can label them. SELECT count(*) INTO v_protected FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND c.metadata->>'origin_collection' = p_origin_collection AND c.metadata->>'quarantined_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' AND c.metadata->>'quarantined_at' <= p_cutoff AND (c.metadata->>'quarantine_expires_at' IS NULL OR c.metadata->>'quarantine_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' OR c.metadata->>'quarantine_expires_at' <= v_now) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash);
SELECT COALESCE(array_agg(s.chash ORDER BY s.chash), '{}'::bytea[]) INTO v_chashes FROM ( SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND c.metadata->>'origin_collection' = p_origin_collection AND c.metadata->>'quarantined_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' AND c.metadata->>'quarantined_at' <= p_cutoff AND (c.metadata->>'quarantine_expires_at' IS NULL OR c.metadata->>'quarantine_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' OR c.metadata->>'quarantine_expires_at' <= v_now) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash) ORDER BY c.chash LIMIT p_row_limit) s;
IF COALESCE(array_length(v_chashes, 1), 0) = 0 THEN RETURN QUERY SELECT 0::bigint, v_protected; RETURN; END IF;
-- The delete re-checks every condition, so a chunk a writer re-referenced, the reaper re-moved (a fresh tag) -- or the client's own expiry already took since the read above survives or is absent, and the count returned -- is what this statement really deleted. WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE AND c.metadata->>'origin_collection' = p_origin_collection AND c.metadata->>'quarantined_at' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' AND c.metadata->>'quarantined_at' <= p_cutoff AND (c.metadata->>'quarantine_expires_at' IS NULL OR c.metadata->>'quarantine_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' OR c.metadata->>'quarantine_expires_at' <= v_now) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash) RETURNING c.chash ) SELECT COALESCE(array_agg(d.chash ORDER BY d.chash), '{}'::bytea[]) INTO v_deleted FROM del d;
v_expired := COALESCE(array_length(v_deleted, 1), 0);
IF v_expired > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'reaper_expire_client_quarantine', p_quarantine_collection, 'engine-reaper', false, v_expired, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_deleted[1:LEAST(v_expired, 5000)]) x), '[]'::jsonb), jsonb_build_object('origin_collection', p_origin_collection, 'cutoff', p_cutoff, 'protected', v_protected, 'row_limit', p_row_limit, 'population', 'client_moved') || CASE WHEN v_expired > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END); END IF;
RETURN QUERY SELECT v_expired, v_protected; END; $$;

