v_expired := COALESCE(array_length(v_deleted, 1), 0);
IF v_expired > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'reaper_expire_client_quarantine', p_quarantine_collection, 'engine-reaper', false, v_expired, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_deleted[1:LEAST(v_expired, 5000)]) x), '[]'::jsonb), jsonb_build_object('origin_collection', p_origin_collection, 'cutoff', p_cutoff, 'protected', v_protected, 'row_limit', p_row_limit, 'population', 'client_moved') || CASE WHEN v_expired > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END); END IF;
